/// <summary>
/// designed from AVA   
/// </summary>
/// <param name = "_entityCtx">_entityCtx</param>
/// <param name = "_dataSourceCtx">_dataSourceCtx</param>
public void mapEntityToDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    next mapEntityToDataSource(_entityCtx, _dataSourceCtx);

    AVAEDISalesTableOrig    salesTableOrig = _dataSourceCtx.getBuffer();

    DirPartyTable salesTakerDP = DirPartyTable::findByName(this.NDXEDISalesTakerName);
    salesTableOrig.NDXEDISalesTaker = HcmWorker::findByPerson(salesTakerDP.RecId).RecId;

}
